let pending;
export async function showPublishedPhotos(target,container){
 const section=document.createElement('section');const h=document.createElement('h3');h.textContent='公開實拍照片';section.append(h);container.append(section);
 try{pending??=fetch('./public-photos.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json();});const photos=(await pending).filter(p=>p.target===target);if(!section.isConnected)return;if(!photos.length){section.append('尚未發布這株樹木的照片。');return;}for(const p of photos){const a=document.createElement('a');a.href=p.kind==='panorama'?`./tour.html?mode=panorama&photo=${encodeURIComponent(p.id)}`:p.url;a.target='_blank';a.rel='noopener';const img=document.createElement('img');img.src=p.url;img.alt=p.title;img.loading='lazy';img.style.cssText='display:block;width:100%;max-height:250px;object-fit:contain;margin:12px 0';const text=document.createElement('p');text.textContent=p.description||p.title;a.append(img,text);section.append(a);}}catch{pending=undefined;if(section.isConnected)section.append('照片目前無法載入，請稍後重新整理。');}
}
